    for row, supply in supplies.items():
        if supply > 0:
            nodes.add(row)
    for set_name, demand in demands.items():
        if demand > 0:
            nodes.add(set_name)
    for row, set_name in usable_edges:
        nodes.add(row)
        nodes.add(set_name)

